const caption = $json.caption_original || $json.caption || '';
const parts = caption.split('|').map(p => p.trim());

const tipo = (parts[1] || '').toLowerCase().replace(/[^a-z]/g, '') || null;
const formaRaw = (parts[2] || '').toLowerCase().replace(/[^a-z]/g, '') || null;
const forma = formaRaw === 'cartao' ? 'cartao' : (formaRaw === 'dinheiro' ? 'dinheiro' : formaRaw);
const cpf = (parts[3] || '').replace(/[^0-9]/g, '') || null;
const valorStr = (parts[4] || '').replace(',', '.');
const valor = parseFloat(valorStr) || 0;
const descricao = parts.slice(5).join('|').trim() || null;

return [{
  json: {
    ...$json,
    tipo_pagador: tipo,
    forma_pagamento: forma,
    cpf_cnpj_pagador: cpf,
    valor,
    descricao
  }
}];

const tipo = (String($json.tipo_pagador || '')).toLowerCase().trim() || null;
const formaInput = (String($json.forma_pagamento || '')).toLowerCase().trim();
let forma = null;
if (formaInput && formaInput !== 'null') {
  if (formaInput.startsWith('cart')) forma = 'cartao';
  else if (formaInput === 'dinheiro') forma = 'dinheiro';
  else forma = formaInput;
}
const cpf = $json.cpf_cnpj_pagador ? String($json.cpf_cnpj_pagador).replace(/[^0-9]/g, '') : null;
const valor = parseFloat($json.valor) || 0;

const combsValidas = [['empresa','cartao'],['empresa','dinheiro'],['particular','cartao'],['particular','dinheiro']];
const erros = [];
const faltantes = [];

if (!tipo) faltantes.push('tipo_pagador');
if (!forma) faltantes.push('forma_pagamento');
if (!cpf) faltantes.push('cpf_cnpj_pagador');
if (valor <= 0) erros.push('Valor deve ser maior que zero');
if (valor > 999999.99) erros.push('Valor acima do limite');

if (cpf && cpf.length !== 11 && cpf.length !== 14) {
  erros.push('CPF/CNPJ invalido: deve ter 11 ou 14 digitos (recebido: ' + cpf.length + ')');
}

if (tipo && forma) {
  const comboOk = combsValidas.some(c => c[0] === tipo && c[1] === forma);
  if (!comboOk) erros.push('Combinacao invalida: ' + tipo + ' + ' + forma + '. Use: empresa/particular + cartao/dinheiro');
}

const faltantesUnicos = [...new Set(faltantes)];
const valido = erros.length === 0 && faltantesUnicos.length === 0;

let motivoErro = null;
if (!valido) {
  const partes = [];
  if (faltantesUnicos.length > 0) partes.push('Campos faltantes: ' + faltantesUnicos.join(', '));
  if (erros.length > 0) partes.push(erros.join(' | '));
  motivoErro = partes.join(' | ');
}

return [{
  json: {
    ...$json,
    tipo_pagador: tipo,
    forma_pagamento: forma,
    cpf_cnpj_pagador: cpf,
    validacao_ok: valido,
    campos_faltantes: faltantesUnicos,
    erros_validacao: erros,
    motivo_erro: motivoErro
  }
}];

const items = $input.all();
const pendente = (items.length > 0 && items[0].json && items[0].json.phone) ? items[0].json : null;
const original = $('WF-DPV.03 - SET | Normalizar Comando').item.json;
return [{ json: { ...original, pendente } }];

const input = $json;
const pendente = input.pendente;
const respostaRaw = (input.caption_original || '').trim();
const resposta = respostaRaw.toUpperCase();

let dadosExtraidos = pendente.dados_extraidos;
if (typeof dadosExtraidos === 'string') {
  try { dadosExtraidos = JSON.parse(dadosExtraidos); } catch(e) { dadosExtraidos = {}; }
}

const phone = input.phone;
const messageId = pendente.message_id;
const step = pendente.step;

function matchChoice(texto, choices) {
  const t = texto.trim();
  for (const c of choices) {
    if (t === c.num) return c.value;
  }
  for (const c of choices) {
    if (c.keys.some(k => texto.includes(k))) return c.value;
  }
  return null;
}

function update(novoStep, updates, mensagem) {
  return {
    action: 'update',
    phone,
    novo_step: novoStep,
    tipo_pagador: updates.tipo_pagador !== undefined ? updates.tipo_pagador : pendente.tipo_pagador,
    forma_pagamento: updates.forma_pagamento !== undefined ? updates.forma_pagamento : pendente.forma_pagamento,
    observacao: updates.observacao !== undefined ? updates.observacao : pendente.observacao,
    mensagem
  };
}

function finalize(extra, motivo) {
  const valorTotal = parseFloat(dadosExtraidos.valor_total) || 0;
  const valorEmpresa = extra.valor_empresa !== undefined ? extra.valor_empresa : null;
  const valorFuncionario = extra.valor_funcionario !== undefined ? extra.valor_funcionario : null;
  const tipoDespesa = extra.tipo_despesa || 'empresa';

  let resumo = 'Despesa registrada!\n' +
    'Estabelecimento: ' + (dadosExtraidos.estabelecimento || '-') + '\n' +
    'Valor: R$ ' + valorTotal.toFixed(2) + '\n' +
    'Pagador: ' + pendente.tipo_pagador + ' + ' + pendente.forma_pagamento;
  if (valorEmpresa !== null && valorFuncionario !== null) {
    resumo += '\nDivisao -> Empresa: R$ ' + valorEmpresa.toFixed(2) + ' | Voce: R$ ' + valorFuncionario.toFixed(2);
  }
  if (tipoDespesa === 'cliente') {
    resumo += '\nA cobrar do cliente';
  }
  if (motivo) resumo += '\n' + motivo;

  return {
    action: 'finalize',
    phone,
    message_id: messageId,
    tipo_pagador: pendente.tipo_pagador,
    forma_pagamento: pendente.forma_pagamento,
    tipo_despesa: tipoDespesa,
    observacao: extra.observacao !== undefined ? extra.observacao : pendente.observacao,
    estabelecimento: dadosExtraidos.estabelecimento || null,
    cnpj: dadosExtraidos.cnpj || null,
    valor_total: valorTotal,
    data_emissao: dadosExtraidos.data_emissao || null,
    categoria: dadosExtraidos.categoria || 'outros',
    itens_json: JSON.stringify(dadosExtraidos).replace(/'/g, "''"),
    valor_empresa: valorEmpresa,
    valor_funcionario: valorFuncionario,
    mensagem: resumo
  };
}

let result;

if (step === 'aguardando_pagador') {
  const escolha = matchChoice(resposta, [
    { num: '1', keys: ['EMPRESA'], value: 'empresa' },
    { num: '2', keys: ['EU'], value: 'particular' },
    { num: '3', keys: ['CLIENTE'], value: 'cliente' }
  ]);
  if (escolha) {
    result = update('aguardando_forma', { tipo_pagador: escolha }, 'Como foi pago?\n1-Cartao\n2-Dinheiro');
  } else {
    result = update(step, {}, 'Nao entendi. Quem pagou?\n1-Empresa\n2-Eu\n3-Cliente');
  }
} else if (step === 'aguardando_forma') {
  const escolha = matchChoice(resposta, [
    { num: '1', keys: ['CARTAO', 'CARTÃO'], value: 'cartao' },
    { num: '2', keys: ['DINHEIRO'], value: 'dinheiro' }
  ]);
  if (!escolha) {
    result = update(step, {}, 'Nao entendi. Como foi pago?\n1-Cartao\n2-Dinheiro');
  } else if (pendente.tipo_pagador === 'cliente') {
    pendente.forma_pagamento = escolha;
    result = finalize({ tipo_despesa: 'cliente' }, null);
  } else {
    result = update('aguardando_observacao', { forma_pagamento: escolha }, 'Observacao?\n1-Dividir\n2-Desconto Bebida\n3-Nao');
  }
} else if (step === 'aguardando_observacao') {
  const escolha = matchChoice(resposta, [
    { num: '1', keys: ['DIVIDIR'], value: 'dividir' },
    { num: '2', keys: ['DESCONTO BEBIDA', 'DESCONTO'], value: 'desconto' },
    { num: '3', keys: ['NAO', 'NÃO'], value: 'nao' }
  ]);
  if (escolha === 'desconto') {
    const itens = Array.isArray(dadosExtraidos.itens) ? dadosExtraidos.itens : [];
    const palavrasAlcool = [
      'CERVEJA', 'VINHO', 'WHISKY', 'WHISKEY', 'CACHACA', 'CACHAÇA', 'DOSE', 'DRINK', 'BEER', 'ALCOOL', 'ÁLCOOL',
      'BRAHMA', 'HEINEKEN', 'SKOL', 'DEVASSA', 'BUDWEISER', 'STELLA', 'CORONA', 'AMSTEL', 'ITAIPAVA', 'ANTARCTICA', 'BOHEMIA'
    ];
    const alcoolicos = itens.filter(it => {
      const desc = String(it.descricao || '').toUpperCase();
      return palavrasAlcool.some(p => desc.includes(p));
    });
    const somaAlcool = alcoolicos.reduce((acc, it) => acc + (parseFloat(it.valor_total) || 0), 0);
    const valorTotal = parseFloat(dadosExtraidos.valor_total) || 0;
    dadosExtraidos.alcoolicos_detectados = { itens: alcoolicos, valor: somaAlcool };
    const motivo = alcoolicos.length
      ? ('Itens identificados: ' + alcoolicos.map(i => i.descricao).join(', ') + ' (R$ ' + somaAlcool.toFixed(2) + ')')
      : 'Nenhum item alcoolico identificado, valor total mantido para a empresa.';
    result = finalize({ valor_funcionario: somaAlcool, valor_empresa: valorTotal - somaAlcool, observacao: 'DESCONTO BEBIDA', tipo_despesa: 'empresa' }, motivo);
  } else if (escolha === 'dividir') {
    result = update('aguardando_divisao', { observacao: 'DIVIDIR' }, 'Informe a divisao. Ex: EMPRESA 80% EU 20%');
  } else if (escolha === 'nao') {
    result = finalize({ observacao: 'NAO', tipo_despesa: 'empresa' }, null);
  } else {
    result = update(step, {}, 'Nao entendi. Observacao?\n1-Dividir\n2-Desconto Bebida\n3-Nao');
  }
} else if (step === 'aguardando_divisao') {
  const matches = [...resposta.matchAll(/(EMPRESA|EU)\s*(\d{1,3})/g)];
  let pctEmpresa = null, pctEu = null;
  for (const m of matches) {
    const val = parseInt(m[2], 10);
    if (m[1] === 'EMPRESA') pctEmpresa = val;
    if (m[1] === 'EU') pctEu = val;
  }
  if (pctEmpresa === null || pctEu === null) {
    result = update(step, {}, 'Nao entendi a divisao. Use o formato: EMPRESA 80% EU 20%');
  } else {
    const valorTotal = parseFloat(dadosExtraidos.valor_total) || 0;
    const valorEmpresa = Math.round(valorTotal * pctEmpresa / 100 * 100) / 100;
    const valorFuncionario = Math.round(valorTotal * pctEu / 100 * 100) / 100;
    result = finalize(
      { valor_empresa: valorEmpresa, valor_funcionario: valorFuncionario, observacao: 'DIVIDIR ' + pctEmpresa + '/' + pctEu, tipo_despesa: 'empresa' },
      null
    );
  }
} else {
  result = update('aguardando_pagador', {}, 'Ocorreu um erro no fluxo. Quem pagou?\n1-Empresa\n2-Eu\n3-Cliente');
}

return [{ json: result }];
